/// maintainer generated it from a CSPRNG and it is reproducible from nothing at all.
/// The distinction is operationally load-bearing: a `derived` key survives a seed
/// restore, an `imported` one is lost unless it was backed up separately, and an
/// `internal` one cannot be recovered by any means once the maintainer's storage is
/// gone. This member is also the only way a consumer can confirm that a `keys/create`
/// request for an `internal` key was honoured rather than silently downgraded to a
/// derived one — see that specification's `internal` member.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const KeyOrigin(String value) {
  static const KeyOrigin derived = KeyOrigin('derived');
  static const KeyOrigin imported = KeyOrigin('imported');
  static const KeyOrigin internal = KeyOrigin('internal');

  /// Every value this specification's schema permits.
  static const List<KeyOrigin> values = <KeyOrigin>[
    derived,
    imported,
    internal
  ];
}

/// How a private half is protected (CONVENTIONS.md §5.2). `software` — stored by the
/// VTA without encryption independent of the host (a plain VTA). `encryptedAtRest` —
/// wrapped under a key the VTA holds outside its store (a hardened VTA). `enclave` —
/// held only inside an attested trusted execution environment, wrapped under a key
/// released only to its measurement (a TEE VTA). `hardwareModule` — held by a hardware
/// security module or cloud key service that performs the operation without releasing
/// the key. `externalCustodian` — not held by this VTA at all: a recovery update key,
/// or an `authenticator` key on a person's device.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const ProtectionClass(String value) {
  static const ProtectionClass software = ProtectionClass('software');
  static const ProtectionClass encryptedAtRest =
      ProtectionClass('encryptedAtRest');
  static const ProtectionClass enclave = ProtectionClass('enclave');
  static const ProtectionClass hardwareModule =
      ProtectionClass('hardwareModule');
  static const ProtectionClass externalCustodian =
      ProtectionClass('externalCustodian');

  /// Every value this specification's schema permits.
  static const List<ProtectionClass> values = <ProtectionClass>[
    software,
    encryptedAtRest,
    enclave,
    hardwareModule,
    externalCustodian
  ];
}

/// The kinds of recovery custodian VTI-KEY-205 admits (CONVENTIONS.md §5.6).
/// `separateKey` — a key held away from every VTA of the identity: an offline key
/// file, a hardware token, a key service whose credentials no such VTA holds, or a key
/// from a recovery mnemonic no such VTA has seen. `vta` — a second VTA with its own
/// seed, operator and host. `thresholdGroup` — a threshold custodian: t of n VTAs
/// holding FROST shares of the key (§5.7).
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const RecoveryCustodianKind(String value) {
  static const RecoveryCustodianKind separateKey =
      RecoveryCustodianKind('separateKey');
  static const RecoveryCustodianKind vta = RecoveryCustodianKind('vta');
  static const RecoveryCustodianKind thresholdGroup =
      RecoveryCustodianKind('thresholdGroup');

  /// Every value this specification's schema permits.
  static const List<RecoveryCustodianKind> values = <RecoveryCustodianKind>[
    separateKey,
    vta,
    thresholdGroup
  ];
}

/// What the operator declares about who holds a recovery key. The VTA cannot verify it
/// — it verifies the proof of possession and refuses a key it generated or can derive
/// — and uses it to route a recovery signing request and to report custody. Custody
/// projection only; never published (VTI-KEY-150, VTI-KEY-206).
class RecoveryCustodian {
  const RecoveryCustodian({
    required this.kind,
    this.did,
    this.participants,
    this.threshold,
  });

  /// Read this payload from a decoded JSON object.
  factory RecoveryCustodian.fromJson(Map<String, dynamic> json) =>
      RecoveryCustodian(
        kind: RecoveryCustodianKind(json['kind'] as String),
        did: json['did'] as String?,
        participants: json['participants'] == null
            ? null
            : (json['participants'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        threshold: json['threshold'] as int?,
      );

  final RecoveryCustodianKind kind;

  /// `vta` only: the custodian VTA's DID, to which the recovering or revoking VTA MAY
  /// send the recovery signing request. Absent, the request is carried out of band.
  final String? did;

  /// `thresholdGroup` only: the participants' VTA DIDs, n of them. A threshold group has
  /// at least three participants, because 2 ≤ t &lt; n (VTI-KEY-210).
  final List<String>? participants;

  /// `thresholdGroup` only: t, the number of participants that together sign. MUST be
  /// less than the number of `participants`.
  final int? threshold;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'kind': kind.value,
        if (did != null) 'did': did!,
        if (participants != null) 'participants': participants!,
        if (threshold != null) 'threshold': threshold!,
      };
}

/// How a key is held. Present only in the custody projection. Carries no key material,
/// and a conforming VTA MUST NOT place any in `ext`.
class IdentityKeyCustody {
  const IdentityKeyCustody({
    this.keyId,
    this.origin,
    required this.exportable,
    required this.neverExportable,
    required this.inBackups,
    required this.protection,
    this.boundary,
    this.destroyed,
    this.custodian,
  });

  /// Read this payload from a decoded JSON object.
  factory IdentityKeyCustody.fromJson(Map<String, dynamic> json) =>
      IdentityKeyCustody(
        keyId: json['keyId'] as String?,
        origin:
            json['origin'] == null ? null : KeyOrigin(json['origin'] as String),
        exportable: json['exportable'] as bool,
        neverExportable: json['neverExportable'] as bool,
        inBackups: json['inBackups'] as bool,
        protection: ProtectionClass(json['protection'] as String),
        boundary: json['boundary'] as String?,
        destroyed: json['destroyed'] as bool?,
        custodian: json['custodian'] == null
            ? null
            : RecoveryCustodian.fromJson(
                json['custodian'] as Map<String, dynamic>),
      );

  /// The custodian record identifier (`keys/*`'s `keyId`) behind this key. Absent for a
  /// key this VTA does not hold (`protection: externalCustodian`).
  final String? keyId;
  final KeyOrigin? origin;

  /// Whether the custodian would release the private half by any operation other than
  /// the VTA's own backup. Always `false` for `attestation` and `update` keys. Stated
  /// explicitly, never absent.
  final bool exportable;

  /// True when no authority can make the key exportable. `true` implies `exportable:
  /// false`.
  final bool neverExportable;

  /// Whether the key, or material it can be re-derived or decrypted from, is in the
  /// VTA's backups or any state transfer. Always `false` for `attestation` and `update`
  /// keys of a level-3 identity (VTI-KEY-112); at level 2 such a key may be in the VTA's
  /// own backup and nowhere else (CONVENTIONS.md §5.5).
  final bool inBackups;
  final ProtectionClass protection;

  /// Opaque, VTA-assigned label of the protection boundary holding the key
  /// (CONVENTIONS.md §5.2). Two keys with the same label are lost or compromised
  /// together. A recovery update key MUST carry a label different from every routine
  /// update key's. Custody projection only; never published.
  final String? boundary;

  /// True once the private half has been destroyed — a retired `attestation` or
  /// `messaging` key. The record survives so the key's past signatures stay
  /// attributable.
  final bool? destroyed;

  /// The recovery update key only: the kind of recovery custodian the operator declared
  /// when committing it (CONVENTIONS.md §5.6). Custody projection only; never published.
  final RecoveryCustodian? custodian;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        if (keyId != null) 'keyId': keyId!,
        if (origin != null) 'origin': origin!.value,
        'exportable': exportable,
        'neverExportable': neverExportable,
        'inBackups': inBackups,
        'protection': protection.value,
        if (boundary != null) 'boundary': boundary!,
        if (destroyed != null) 'destroyed': destroyed!,
        if (custodian != null) 'custodian': custodian!.toJson(),
      };
}

/// Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a
/// reverse-DNS namespace; structure under each namespace is opaque to the framework.
typedef Ext = Map<String, dynamic>;

/// One key in one role. A key is in exactly one role for its whole life; a change of
/// role is a retirement from one and an addition to another, with fresh material under
/// a fresh identifier.
class IdentityRoleKey {
  const IdentityRoleKey({
    this.verificationMethod,
    required this.role,
    this.updateKeyClass,
    this.relationships,
    required this.keyType,
    this.publicKeyMultibase,
    this.commitment,
    required this.state,
    this.publishedInVersionId,
    this.removedInVersionId,
    this.activatesAt,
    this.retireAfter,
    this.compromisedSince,
    this.rotationId,
    this.label,
    this.custody,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory IdentityRoleKey.fromJson(Map<String, dynamic> json) =>
      IdentityRoleKey(
        verificationMethod: json['verificationMethod'] as String?,
        role: IdentityKeyRole(json['role'] as String),
        updateKeyClass: json['updateKeyClass'] == null
            ? null
            : UpdateKeyClass(json['updateKeyClass'] as String),
        relationships: json['relationships'] == null
            ? null
            : (json['relationships'] as List<dynamic>)
                .map((e) => DidVerificationRelationship(e as String))
                .toList(),
        keyType: KeyType(json['keyType'] as String),
        publicKeyMultibase: json['publicKeyMultibase'] as String?,
        commitment: json['commitment'] as String?,
        state: KeyLifecycleState(json['state'] as String),
        publishedInVersionId: json['publishedInVersionId'] as String?,
        removedInVersionId: json['removedInVersionId'] as String?,
        activatesAt: json['activatesAt'] as String?,
        retireAfter: json['retireAfter'] as String?,
        compromisedSince: json['compromisedSince'] as String?,
        rotationId: json['rotationId'] as String?,
        label: json['label'] as String?,
        custody: json['custody'] == null
            ? null
            : IdentityKeyCustody.fromJson(
                json['custody'] as Map<String, dynamic>),
        ext: json['ext'] as Map<String, dynamic>?,
      );

  /// The full verification-method identifier (`did#fragment`) the document publishes the
  /// key under and lists in `keyRoles`. Absent for `update` keys, which are never
  /// role-bound verification methods (VTI-KEY-093). A VTA minting a method SHOULD derive
  /// its fragment from the key (VTI-KEY-150).
  final String? verificationMethod;
  final IdentityKeyRole role;
  final UpdateKeyClass? updateKeyClass;

  /// The relationships the key is (or, while `pending`, will be) listed in: always
  /// exactly its role's one relationship. Empty for `update`, `retired` and `revoked`
  /// keys.
  final List<DidVerificationRelationship>? relationships;
  final KeyType keyType;

  /// The public half, multibase-encoded, exactly as published. Absent for a `committed`
  /// update key, whose public half the identifier has not yet revealed.
  final String? publicKeyMultibase;

  /// For a `committed` update key: the commitment the identifier publishes (a did:webvh
  /// `nextKeyHashes` entry, a KERI next-key digest), in the method's own encoding.
  final String? commitment;
  final KeyLifecycleState state;

  /// The method's version identifier of the change that first published the key or its
  /// commitment (method-profiles/: a did:webvh `versionId`, a KERI event's sequence
  /// number and digest). Absent while `pending`.
  final String? publishedInVersionId;

  /// Version identifier of the change that retired or revoked the key.
  final String? removedInVersionId;

  /// For a `staged` key: when the VTA will begin using it — no earlier than the
  /// publishing change's cache horizon.
  final String? activatesAt;

  /// For a `retiring` key: the end of its overlap. Custody projection only.
  final String? retireAfter;

  /// For a `revoked` key: the compromise time (VTI-KEY-121), published as the
  /// verification method's `revoked` value. Where it cannot be established, the time the
  /// key was first published.
  final String? compromisedSince;

  /// The rotation this key was introduced or retired by.
  final String? rotationId;

  /// Operator-facing label. Custody projection only.
  final String? label;
  final IdentityKeyCustody? custody;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        if (verificationMethod != null)
          'verificationMethod': verificationMethod!,
        'role': role.value,
        if (updateKeyClass != null) 'updateKeyClass': updateKeyClass!.value,
        if (relationships != null)
          'relationships': relationships!.map((e) => e.value).toList(),
        'keyType': keyType.value,
        if (publicKeyMultibase != null)
          'publicKeyMultibase': publicKeyMultibase!,
        if (commitment != null) 'commitment': commitment!,
        'state': state.value,
        if (publishedInVersionId != null)
          'publishedInVersionId': publishedInVersionId!,
        if (removedInVersionId != null)
          'removedInVersionId': removedInVersionId!,
        if (activatesAt != null) 'activatesAt': activatesAt!,
        if (retireAfter != null) 'retireAfter': retireAfter!,
        if (compromisedSince != null) 'compromisedSince': compromisedSince!,
        if (rotationId != null) 'rotationId': rotationId!,
        if (label != null) 'label': label!,
        if (custody != null) 'custody': custody!.toJson(),
        if (ext != null) 'ext': ext!,
      };
}

/// `planned` — a successor was staged, activated, and the predecessor retired on the
/// operator's schedule. `compromise` — a key was revoked and, where the role would
/// otherwise be empty, replaced in the same change. `addition` — a key joined a role
/// without anything leaving it. `recovery` — the identifier's update authority moved
/// to the committed recovery key, because the VTA's own update keys were lost or may
/// be in someone else's hands.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const KeyChangeKind(String value) {
  static const KeyChangeKind planned = KeyChangeKind('planned');
  static const KeyChangeKind compromise = KeyChangeKind('compromise');
  static const KeyChangeKind addition = KeyChangeKind('addition');
  static const KeyChangeKind recovery = KeyChangeKind('recovery');

  /// Every value this specification's schema permits.
  static const List<KeyChangeKind> values = <KeyChangeKind>[
    planned,
    compromise,
    addition,
    recovery
  ];
}

/// `pendingApproval` — awaiting the approvals the VTA's policy requires; nothing is
/// published. `awaitingRecoveryProof` — approved, and waiting for the recovery
/// custodian's proof over the change; nothing is published. `staged` — successor
/// published, not yet used. `overlapping` — successor active, predecessor `retiring`.
/// `completed` — every predecessor retired, or the change is published and any overlap
/// it began has ended. `aborted` — the successor was retired instead of the
/// predecessor, or a revocation superseded the change. `expired` — the approvals or
/// the recovery proof did not arrive before the preview expired; nothing was
/// published.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const KeyChangeState(String value) {
  static const KeyChangeState pendingApproval =
      KeyChangeState('pendingApproval');
  static const KeyChangeState awaitingRecoveryProof =
      KeyChangeState('awaitingRecoveryProof');
  static const KeyChangeState staged = KeyChangeState('staged');
  static const KeyChangeState overlapping = KeyChangeState('overlapping');
  static const KeyChangeState completed = KeyChangeState('completed');
  static const KeyChangeState aborted = KeyChangeState('aborted');
  static const KeyChangeState expired = KeyChangeState('expired');

  /// Every value this specification's schema permits.
  static const List<KeyChangeState> values = <KeyChangeState>[
    pendingApproval,
    awaitingRecoveryProof,
    staged,
    overlapping,
    completed,
    aborted,
    expired
  ];
}

/// One change to a role's key set, from preview to completion. The identifier's
/// history is the authority for what was published; this record adds which change was
/// which and, in the custody projection, who asked, who approved, and why.
class KeyChangeRecord {
  const KeyChangeRecord({
    required this.rotationId,
    required this.role,
    required this.kind,
    required this.state,
    this.predecessors,
    this.successors,
    this.startedInVersionId,
    this.endedInVersionId,
    this.startedAt,
    this.cacheHorizonAt,
    this.activatesAt,
    this.overlapUntil,
    this.autoRetire,
    this.endedAt,
    this.initiatedBy,
    this.approvals,
    this.reason,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory KeyChangeRecord.fromJson(Map<String, dynamic> json) =>
      KeyChangeRecord(
        rotationId: json['rotationId'] as String,
        role: IdentityKeyRole(json['role'] as String),
        kind: KeyChangeKind(json['kind'] as String),
        state: KeyChangeState(json['state'] as String),
        predecessors: json['predecessors'] == null
            ? null
            : (json['predecessors'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        successors: json['successors'] == null
            ? null
            : (json['successors'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        startedInVersionId: json['startedInVersionId'] as String?,
        endedInVersionId: json['endedInVersionId'] as String?,
        startedAt: json['startedAt'] as String?,
        cacheHorizonAt: json['cacheHorizonAt'] as String?,
        activatesAt: json['activatesAt'] as String?,
        overlapUntil: json['overlapUntil'] as String?,
        autoRetire: json['autoRetire'] as bool?,
        endedAt: json['endedAt'] as String?,
        initiatedBy: json['initiatedBy'] as String?,
        approvals: json['approvals'] == null
            ? null
            : KeyChangeApprovalState.fromJson(
                json['approvals'] as Map<String, dynamic>),
        reason: json['reason'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  final String rotationId;
  final IdentityKeyRole role;
  final KeyChangeKind kind;
  final KeyChangeState state;

  /// Verification-method identifiers (for `update`, public keys or commitments) leaving
  /// the role.
  final List<String>? predecessors;

  /// Verification-method identifiers (for `update`, public keys or commitments) entering
  /// the role.
  final List<String>? successors;
  final String? startedInVersionId;
  final String? endedInVersionId;
  final String? startedAt;

  /// Planned rotations: the publishing change's cache horizon (CONVENTIONS.md §10.1).
  /// The switch and any retirement happen no earlier.
  final String? cacheHorizonAt;

  /// When the successor becomes `active` and the predecessor `retiring`; never before
  /// `cacheHorizonAt`.
  final String? activatesAt;

  /// Custody projection only. End of the overlap.
  final String? overlapUntil;

  /// Custody projection only. Whether the VTA retires the predecessor itself at
  /// `overlapUntil`.
  final bool? autoRetire;
  final String? endedAt;

  /// Custody projection only. VID of the administrator whose signed request started the
  /// change.
  final String? initiatedBy;
  final KeyChangeApprovalState? approvals;

  /// Custody projection only. The operator's stated reason. Never published.
  final String? reason;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'rotationId': rotationId,
        'role': role.value,
        'kind': kind.value,
        'state': state.value,
        if (predecessors != null) 'predecessors': predecessors!,
        if (successors != null) 'successors': successors!,
        if (startedInVersionId != null)
          'startedInVersionId': startedInVersionId!,
        if (endedInVersionId != null) 'endedInVersionId': endedInVersionId!,
        if (startedAt != null) 'startedAt': startedAt!,
        if (cacheHorizonAt != null) 'cacheHorizonAt': cacheHorizonAt!,
        if (activatesAt != null) 'activatesAt': activatesAt!,
        if (overlapUntil != null) 'overlapUntil': overlapUntil!,
        if (autoRetire != null) 'autoRetire': autoRetire!,
        if (endedAt != null) 'endedAt': endedAt!,
        if (initiatedBy != null) 'initiatedBy': initiatedBy!,
        if (approvals != null) 'approvals': approvals!.toJson(),
        if (reason != null) 'reason': reason!,
        if (ext != null) 'ext': ext!,
      };
}

/// A file the identifier's method publishes, as the method profile names it
/// (`did.jsonl` for did:webvh, `did.json` and `keri.cesr` for did:webs).
class PublishedArtifact {
  const PublishedArtifact({
    required this.name,
    required this.mediaType,
    required this.content,
  });

  /// Read this payload from a decoded JSON object.
  factory PublishedArtifact.fromJson(Map<String, dynamic> json) =>
      PublishedArtifact(
        name: json['name'] as String,
        mediaType: json['mediaType'] as String,
        content: json['content'] as String,
      );

  final String name;
  final String mediaType;

  /// The artefact's content, or for an append-only artefact the appended part, as text.
  final String content;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'name': name,
        'mediaType': mediaType,
        'content': content,
      };
}

/// How the change reaches resolvers.
class Publication {
  const Publication({
    required this.selfPublish,
    this.artifacts,
  });

  /// Read this payload from a decoded JSON object.
  factory Publication.fromJson(Map<String, dynamic> json) => Publication(
        selfPublish: json['selfPublish'] as bool,
        artifacts: json['artifacts'] == null
            ? null
            : (json['artifacts'] as List<dynamic>)
                .map((e) =>
                    PublishedArtifact.fromJson(e as Map<String, dynamic>))
                .toList(),
      );

  /// True when no hosting service holds the identifier for the VTA: the caller must
  /// publish `artifacts`, and until it does resolvers see the previous version.
  final bool selfPublish;

  /// Present when `selfPublish` is true.
  final List<PublishedArtifact>? artifacts;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'selfPublish': selfPublish,
        if (artifacts != null)
          'artifacts': artifacts!.map((e) => e.toJson()).toList(),
      };
}

/// VTA DIDs — Keys Rotate — response payload
class Response {
  const Response({
    required this.did,
    required this.outcome,
    this.preview,
    this.approvals,
    this.newVersionId,
    this.keys,
    this.rotation,
    this.publication,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory Response.fromJson(Map<String, dynamic> json) => Response(
        did: json['did'] as String,
        outcome: KeyChangeOutcome(json['outcome'] as String),
        preview: json['preview'] == null
            ? null
            : IdentityChangePreview.fromJson(
                json['preview'] as Map<String, dynamic>),
        approvals: json['approvals'] == null
            ? null
            : KeyChangeApprovalState.fromJson(
                json['approvals'] as Map<String, dynamic>),
        newVersionId: json['newVersionId'] as String?,
        keys: json['keys'] == null
            ? null
            : (json['keys'] as List<dynamic>)
                .map((e) => IdentityRoleKey.fromJson(e as Map<String, dynamic>))
                .toList(),
        rotation: json['rotation'] == null
            ? null
            : KeyChangeRecord.fromJson(
                json['rotation'] as Map<String, dynamic>),
        publication: json['publication'] == null
            ? null
            : Publication.fromJson(json['publication'] as Map<String, dynamic>),
        ext: json['ext'] as Map<String, dynamic>?,
      );

  final String did;
  final KeyChangeOutcome outcome;

  /// Present when `outcome` is `preview`, `pendingApproval` or `awaitingRecoveryProof`:
  /// the plan, and what an approval is bound to.
  final IdentityChangePreview? preview;

  /// Present when `outcome` is `pendingApproval`.
  final KeyChangeApprovalState? approvals;

  /// Present when `outcome` is `applied`: the version identifier of the change. Pass it
  /// as the next change's `expectedVersionId`.
  final String? newVersionId;

  /// Every key whose state this change sets or would set, after the change.
  final List<IdentityRoleKey>? keys;
  final KeyChangeRecord? rotation;

  /// Present when `outcome` is `applied`.
  final Publication? publication;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'did': did,
        'outcome': outcome.value,
        if (preview != null) 'preview': preview!.toJson(),
        if (approvals != null) 'approvals': approvals!.toJson(),
        if (newVersionId != null) 'newVersionId': newVersionId!,
        if (keys != null) 'keys': keys!.map((e) => e.toJson()).toList(),
        if (rotation != null) 'rotation': rotation!.toJson(),
        if (publication != null) 'publication': publication!.toJson(),
        if (ext != null) 'ext': ext!,
      };
}

/// A recovery key offered for commitment at level 3 (CONVENTIONS.md §5.3). The VTA
/// computes the method's commitment from it, verifies `proofOfPossession`, and then
/// keeps only the commitment. The key MUST be held by a recovery custodian in a
/// protection boundary other than the VTA's (§5.6); a VTA MUST refuse one it generated
/// or can derive (`vta/dids:recoveryCommitmentRequired`). A threshold custodian's key
/// is an ordinary Ed25519 key, and its proof of possession an ordinary Ed25519
/// signature (§5.7).
class RecoveryCommitment {
  const RecoveryCommitment({
    required this.keyType,
    required this.publicKeyMultibase,
    this.proofOfPossession,
    this.label,
    this.custodian,
  });

  /// Read this payload from a decoded JSON object.
  factory RecoveryCommitment.fromJson(Map<String, dynamic> json) =>
      RecoveryCommitment(
        keyType: KeyType(json['keyType'] as String),
        publicKeyMultibase: json['publicKeyMultibase'] as String,
        proofOfPossession: json['proofOfPossession'] as String?,
        label: json['label'] as String?,
        custodian: json['custodian'] == null
            ? null
            : RecoveryCustodian.fromJson(
                json['custodian'] as Map<String, dynamic>),
      );

  final KeyType keyType;

  /// The recovery key's public half. Not published by the VTA where the method commits
  /// by hash.
  final String publicKeyMultibase;

  /// Multibase signature by the recovery key over the UTF-8 bytes of
  /// `vta-dids-recovery-commitment/v1`, a zero byte, and the request's `previewId`.
  /// Absent on a dry run, which is how the `previewId` is obtained; REQUIRED on the
  /// apply request, and the only member besides `previewId`, `dryRun` and
  /// `recoveryProof` that may differ between the two.
  final String? proofOfPossession;

  /// Operator-facing name of the custodian. Custody projection only; never published.
  final String? label;
  final RecoveryCustodian? custodian;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'keyType': keyType.value,
        'publicKeyMultibase': publicKeyMultibase,
        if (proofOfPossession != null) 'proofOfPossession': proofOfPossession!,
        if (label != null) 'label': label!,
        if (custodian != null) 'custodian': custodian!.toJson(),
      };
}

/// Plan and start the planned rotation of one role of a key-role identity: successors
/// staged, switched at the cache horizon, predecessors retired at the end of the
/// overlap. For `update`, the authority moves to its committed routine successor, or
/// the recovery commitment is replaced.
class Payload {
  const Payload({
    required this.did,
    required this.role,
    this.replace,
    this.keyType,
    this.activatesAt,
    this.overlapUntil,
    this.autoRetire,
    this.recoveryCommitment,
    this.useRecoveryKey,
    this.recoveryProof,
    this.label,
    this.expectedVersionId,
    this.dryRun,
    this.previewId,
    this.reason,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory Payload.fromJson(Map<String, dynamic> json) => Payload(
        did: json['did'] as String,
        role: IdentityKeyRole(json['role'] as String),
        replace: json['replace'] == null
            ? null
            : (json['replace'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        keyType:
            json['keyType'] == null ? null : KeyType(json['keyType'] as String),
        activatesAt: json['activatesAt'] as String?,
        overlapUntil: json['overlapUntil'] as String?,
        autoRetire: json['autoRetire'] as bool?,
        recoveryCommitment: json['recoveryCommitment'] == null
            ? null
            : RecoveryCommitment.fromJson(
                json['recoveryCommitment'] as Map<String, dynamic>),
        useRecoveryKey: json['useRecoveryKey'] as bool?,
        recoveryProof: json['recoveryProof'] as Map<String, dynamic>?,
        label: json['label'] as String?,
        expectedVersionId: json['expectedVersionId'] as String?,
        dryRun: json['dryRun'] as bool?,
        previewId: json['previewId'] as String?,
        reason: json['reason'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  /// The key-role identity, by DID (for a `did:scid` identity, the DID without `src`).
  final String did;

  /// The one role to rotate. `authenticator` is refused
  /// (`vta/dids:notApplicableToRole`).
  final IdentityKeyRole role;

  /// Verification methods of the role to rotate. Absent rotates every active key of the
  /// role. Not for `update`.
  final List<String>? replace;

  /// Successors' algorithm. Absent keeps each predecessor's (CONVENTIONS.md §14). Not
  /// for `update`.
  final KeyType? keyType;

  /// When successors switch in; no earlier than the cache horizon, which is the default.
  /// Not for `update`.
  final String? activatesAt;

  /// End of the overlap; after `activatesAt`. Not for `update`.
  final String? overlapUntil;

  /// Whether the VTA retires predecessors itself at `overlapUntil`. Absent reads as
  /// true. Not for `update`.
  final bool? autoRetire;

  /// `update` only, level 3 only (`vta/dids:assuranceLevelMismatch` below it): replace
  /// the recovery commitment with this key (CONVENTIONS.md §5.3, §6.5), authorized by
  /// the current recovery key (`useRecoveryKey`) or, where that key is lost, by a
  /// quorum. Absent moves the routine authority and carries the recovery commitment
  /// forward.
  final RecoveryCommitment? recoveryCommitment;

  /// `update` with `recoveryCommitment` only, level 3: `true` has the current recovery
  /// key authorize the replacement — the change reveals it and commits the new one, and
  /// the VTA answers `awaitingRecoveryProof` until the custodian's `recoveryProof`
  /// arrives; no quorum is then required (VTI-KEY-181). Absent or `false`, for a
  /// recovery key that is lost: the replacement is authorized by the routine key with
  /// the quorum of CONVENTIONS.md §6.5.
  final bool? useRecoveryKey;

  /// With `useRecoveryKey: true` only: the recovery custodian's proof over
  /// `preview.recoverySigning.unsignedChange`, in the method profile's form. A threshold
  /// custodian's is an ordinary Ed25519 proof (CONVENTIONS.md §5.7).
  final Map<String, dynamic>? recoveryProof;
  final String? label;

  /// Optimistic-concurrency precondition: the version identifier (method profile §3) the
  /// caller based this change on, for example `keys/list`'s `versionId`. The VTA MUST
  /// refuse with `vta/dids:versionConflict` if the identity has moved past it. Not
  /// optional for anything a person looked at.
  final String? expectedVersionId;

  /// Compute and return the preview without writing anything but the plan
  /// (CONVENTIONS.md §6.1). Absent reads as false.
  final bool? dryRun;

  /// Apply exactly the plan a previous dry run of this same request returned, or nothing
  /// (CONVENTIONS.md §6.1); what every approval is bound to.
  final String? previewId;

  /// Why the change is being made, for the audit trail and for the other approvers.
  /// Never published.
  final String? reason;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'did': did,
        'role': role.value,
        if (replace != null) 'replace': replace!,
        if (keyType != null) 'keyType': keyType!.value,
        if (activatesAt != null) 'activatesAt': activatesAt!,
        if (overlapUntil != null) 'overlapUntil': overlapUntil!,
        if (autoRetire != null) 'autoRetire': autoRetire!,
        if (recoveryCommitment != null)
          'recoveryCommitment': recoveryCommitment!.toJson(),
        if (useRecoveryKey != null) 'useRecoveryKey': useRecoveryKey!,
        if (recoveryProof != null) 'recoveryProof': recoveryProof!,
        if (label != null) 'label': label!,
        if (expectedVersionId != null) 'expectedVersionId': expectedVersionId!,
        if (dryRun != null) 'dryRun': dryRun!,
        if (previewId != null) 'previewId': previewId!,
        if (reason != null) 'reason': reason!,
        if (ext != null) 'ext': ext!,
      };
}

